// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.connectivity.callimport timber.log.Timberimport android.content.Contextimport android.media.AudioManagerimport com.roshan.persona.connectivity.model.BouncerModeimport com.roshan.persona.connectivity.model.CallStateimport com.roshan.persona.connectivity.model.SpamLevelimport com.roshan.persona.connectivity.contact.ContactSearcherimport kotlinx.coroutines.CoroutineDispatcherimport kotlinx.coroutines.delayimport kotlinx.coroutines.flow.Flowimport kotlinx.coroutines.flow.MutableSharedFlowimport kotlinx.coroutines.flow.asSharedFlowimport kotlinx.coroutines.withContextimport java.util.concurrent.atomic.AtomicReference/** * NOUS — Call Engine (Module 11 v3 — Step 11.3, CRITICAL). * * Combines 4 components for complete call management: * *  1. **CallController** — place/answer/reject/hangup via [CallService]. *  2. **CallStateMonitor** — live call state (RINGING/OFFHOOK/IDLE) via Flow. *  3. **EmergencyDetector** — 112/911/100 bypass ALL gates. *  4. **ActiveCallBouncer** (v3 elite) — intercepts unknown calls, asks purpose. * * ## Incoming call flow (per strategy v3 §"Active AI Call Screening") * * ``` * Phone rings → CallStateMonitor detects RINGING *   ↓ * 1. EmergencyDetector.check(phoneNumber) → emergency? → ring normally (bypass) * 2. SpamDetectorEngine.classify(phoneNumber) *    → SPAM → auto-reject (if autoBlockSpam) OR ask user *    → HIGH_RISK → ask user *    → SAFE (in contacts) → ring normally + TTS caller name *    → LOW_RISK (unknown) → ActiveCallBouncer activates: *       a. Answer the call automatically *       b. TTS: "Hello, please state the purpose of your call." *       c. Transcribe caller's response (Module 5 STT) *       d. Display transcription on screen *       e. If telemarketer → auto-hangup *       f. If legitimate → user taps "Accept" to take the call * ``` * * ## Outgoing call flow * * ``` * User: "Call mom" *   ↓ * 1. ContactSearcher.findByName("mom") → contact * 2. EmergencyDetector.check(contact.primaryPhone) → not emergency * 3. VoiceVerification.verify() → matches owner? (anti-prank) * 4. CallController.placeCall(contact.primaryPhone, simSlot) * 5. CallStateMonitor monitors: DIALING → OFFHOOK → DISCONNECTED * 6. TTS: "Calling Mom." (persona-styled) * ``` * * @see <a href="docs/strategy/module-11-connectivity-strategy-v3.md">§CallEngine + ActiveCallBouncer</a> */class CallEngine(    private val callService: CallService,    private val spamDetector: SpamDetectorEngine,    private val contactSearcher: ContactSearcher,    private val bouncerTts: BouncerTtsInterface,    private val emergencyNumbers: Set<String>,    private val bouncerMode: BouncerMode,    private val activeBouncerEnabled: Boolean,    private val bouncerGreeting: String,    private val dispatcher: CoroutineDispatcher,    private val audioManager: AudioManager? = null,) {    /**     * Convenience constructor accepting a [Context] for the AudioManager     * (used by [muteCall]/[unmuteCall]/[toggleSpeaker]/[holdCall]/[resumeCall]).     */    constructor(        callService: CallService,        spamDetector: SpamDetectorEngine,        contactSearcher: ContactSearcher,        bouncerTts: BouncerTtsInterface,        emergencyNumbers: Set<String>,        bouncerMode: BouncerMode,        activeBouncerEnabled: Boolean,        bouncerGreeting: String,        dispatcher: CoroutineDispatcher,        context: Context,    ) : this(        callService = callService,        spamDetector = spamDetector,        contactSearcher = contactSearcher,        bouncerTts = bouncerTts,        emergencyNumbers = emergencyNumbers,        bouncerMode = bouncerMode,        activeBouncerEnabled = activeBouncerEnabled,        bouncerGreeting = bouncerGreeting,        dispatcher = dispatcher,        audioManager = context.getSystemService(Context.AUDIO_SERVICE) as? AudioManager,    )    private val currentState = AtomicReference(CallState.IDLE)    /** Live call state — observe via [callState]. */    private val _callState = MutableSharedFlow<CallState>(extraBufferCapacity = 16)    val callState: Flow<CallState> = _callState.asSharedFlow()    /** Get the current call state. */    fun getCurrentState(): CallState = currentState.get()    // ─── Outgoing calls ────────────────────────────────────────────────────    /**     * Place an outgoing call.     *     * @param phoneNumber the number to call.     * @param simSlot which SIM to use (null = default/preferred).     * @return [CallResult] — PLACED, EMERGENCY_BYPASS, or FAILED.     */    suspend fun placeCall(phoneNumber: String, simSlot: Int? = null): CallResult = withContext(dispatcher) {        // CRITICAL FIX #34: Validate phone number before placing call        if (!isValidPhoneNumber(phoneNumber)) {            Timber.tag(TAG).w("Invalid phone number format for outgoing call: $phoneNumber")            return@withContext CallResult.FAILED("Invalid phone number format")        }                Timber.tag(TAG).i("Placing call to ${maskPhoneNumber(phoneNumber)} (sim=$simSlot)")        // 1. Emergency check — bypass all gates.        if (isEmergency(phoneNumber)) {            Timber.tag(TAG).i("Emergency number detected — bypassing all gates.")            val placed = callService.placeCall(phoneNumber, simSlot)            return@withContext if (placed) CallResult.EMERGENCY_BYPASS else CallResult.FAILED("Call failed")        }        // 2. Place the call.        val placed = callService.placeCall(phoneNumber, simSlot)        if (placed) {            updateState(CallState.DIALING)            CallResult.PLACED        } else {            CallResult.FAILED("CallService.placeCall returned false")        }    }    // ─── Incoming call handling ────────────────────────────────────────────    /**     * Handle an incoming call (called by CallStateMonitor when RINGING detected).     *     * @param phoneNumber the caller's phone number.     * @return [IncomingCallAction] — what NOUS should do.     */    suspend fun handleIncomingCall(phoneNumber: String): IncomingCallAction = withContext(dispatcher) {        updateState(CallState.RINGING)                // CRITICAL FIX #35: Validate incoming phone number        val sanitizedNumber = phoneNumber.ifBlank { "UNKNOWN" }        Timber.tag(TAG).i("Incoming call from ${maskPhoneNumber(sanitizedNumber)}")        // 1. Record the call for pattern detection.        spamDetector.recordIncomingCall(phoneNumber)        // 2. Emergency check — always ring normally.        if (isEmergency(phoneNumber)) {            return@withContext IncomingCallAction.RingNormally("Emergency number")        }        // 3. Spam detection.        val spamClassification = spamDetector.classify(phoneNumber)        // 4. Bouncer-mode-driven auto-reject (Strategy §"Active AI Call Screening"):        //    - OFF → never auto-reject.        //    - SPAM_ONLY → reject SPAM/FRAUD.        //    - SUSPECT_AND_SPAM → reject SUSPECT + SPAM + FRAUD.        if (bouncerMode.shouldReject(spamClassification.level)) {            Timber.tag(TAG).i("Auto-rejecting (mode=$bouncerMode, level=${spamClassification.level}): ${spamClassification.reason}")            callService.rejectCall()            updateState(CallState.DISCONNECTED)            return@withContext IncomingCallAction.AutoRejected(spamClassification)        }        when (spamClassification.level) {            SpamLevel.SPAM, SpamLevel.FRAUD, SpamLevel.SUSPECT -> {                // Didn't auto-reject — ask the user.                IncomingCallAction.AskUser(spamClassification)            }            SpamLevel.HAM -> {                // In contacts — ring normally + announce caller name.                val contact = contactSearcher.findByPhoneNumber(phoneNumber)                val callerName = contact?.displayName ?: "Unknown"                IncomingCallAction.RingNormally(callerName)            }            // Legacy aliases — route via the canonical levels above.            @Suppress("DEPRECATION")            SpamLevel.SAFE -> {                val contact = contactSearcher.findByPhoneNumber(phoneNumber)                val callerName = contact?.displayName ?: "Unknown"                IncomingCallAction.RingNormally(callerName)            }            @Suppress("DEPRECATION")            SpamLevel.LOW_RISK -> {                // Unknown number — activate Bouncer if enabled.                if (activeBouncerEnabled) {                    IncomingCallAction.ActivateBouncer(phoneNumber, spamClassification)                } else {                    IncomingCallAction.RingNormally("Unknown number")                }            }            @Suppress("DEPRECATION")            SpamLevel.SUSPICIOUS, @Suppress("DEPRECATION") SpamLevel.HIGH_RISK -> {                IncomingCallAction.AskUser(spamClassification)            }        }    }    // ─── Active Call Bouncer (v3 elite) ────────────────────────────────────    /**     * Activate the Call Bouncer — answer the call + ask caller's purpose.     *     * Called when [handleIncomingCall] returns [IncomingCallAction.ActivateBouncer].     *     * ## Flow (per strategy v3 §"Active AI Call Screening")     *     * 1. Answer the call automatically.     * 2. TTS speaks [bouncerGreeting] to the caller.     * 3. Listen to caller's response (Module 5 STT transcribes).     * 4. Display transcription on screen.     * 5. If telemarketer keywords detected → auto-hangup.     * 6. If legitimate → user taps "Accept" to take the call.     *     * @param phoneNumber the caller's phone number.     * @return [BouncerResult] — what happened during the bounce.     */    suspend fun activateBouncer(phoneNumber: String): BouncerResult = withContext(dispatcher) {        Timber.tag(TAG).i("Activating Call Bouncer for $phoneNumber")        // 1. Answer the call.        val answered = callService.answerCall()        if (!answered) {            return@withContext BouncerResult.FAILED("Could not answer call")        }        updateState(CallState.OFFHOOK)        // 2. Speak the bouncer greeting.        bouncerTts.speak(bouncerGreeting)        // 3. Listen to caller's response (v1: return AWAITING_USER_DECISION).        //    Real impl pipes call audio to Module 5 STT for transcription.        //    For v1, we return AWAITING_USER_DECISION — the UI shows        //    "NOUS is screening this call. Tap to accept or reject."        delay(BOUNCER_LISTEN_DELAY_MS)        return@withContext BouncerResult.AWAITING_USER_DECISION(            phoneNumber = phoneNumber,            transcription = null,  // v2+: STT transcribes caller's response        )    }    /**     * Accept a bounced call (user taps "Accept").     * The call is already connected — just hand it to the user.     */    fun acceptBouncedCall() {        Timber.tag(TAG).i("User accepted bounced call.")        // Call is already OFFHOOK — nothing to do, user takes over.    }    /**     * Reject a bounced call (user taps "Reject" or auto-reject telemarketer).     */    suspend fun rejectBouncedCall() = withContext(dispatcher) {        Timber.tag(TAG).i("Rejecting bounced call.")        callService.endCall()        updateState(CallState.DISCONNECTED)    }    // ─── Call control ──────────────────────────────────────────────────────    /** Answer the current incoming call. */    suspend fun answerCall(): Boolean = withContext(dispatcher) {        val result = callService.answerCall()        if (result) updateState(CallState.OFFHOOK)        result    }    /** Reject the current incoming call. */    suspend fun rejectCall(): Boolean = withContext(dispatcher) {        val result = callService.rejectCall()        if (result) updateState(CallState.DISCONNECTED)        result    }    /** End the current call. */    suspend fun endCall(): Boolean = withContext(dispatcher) {        val result = callService.endCall()        if (result) updateState(CallState.DISCONNECTED)        result    }    // ─── In-call control (mute / speaker / hold) — Strategy §11.3 ──────────    /**     * Mute the microphone during the current call.     *     * Uses [AudioManager.setMicrophoneMute]. Note: this only affects NOUS's     * local mic capture — the call line itself is owned by the system     * `InCallService` and may not respond to mute from a third-party app.     * Strategy §"CallEngine" explicitly notes: "use reflection on     * InCallService if needed, or document limitation."     *     * @return true if the AudioMgr mute call succeeded.     */    fun muteCall(): Boolean {        val am = audioManager ?: run {            Timber.tag(TAG).w("muteCall: AudioManager unavailable.")            return false        }        return try {            am.isMicrophoneMute = true            Timber.tag(TAG).i("Microphone muted.")            true        } catch (t: Throwable) {            Timber.tag(TAG).e(t, "muteCall failed")            false        }    }    /**     * Unmute the microphone during the current call.     */    fun unmuteCall(): Boolean {        val am = audioManager ?: return false        return try {            am.isMicrophoneMute = false            Timber.tag(TAG).i("Microphone unmuted.")            true        } catch (t: Throwable) {            Timber.tag(TAG).e(t, "unmuteCall failed")            false        }    }    /**     * Toggle the speakerphone on/off during the current call.     *     * @return the new speaker state (true = ON, false = OFF).     */    fun toggleSpeaker(): Boolean {        val am = audioManager ?: return false        return try {            val newState = !am.isSpeakerphoneOn            am.isSpeakerphoneOn = newState            Timber.tag(TAG).i("Speakerphone toggled → $newState.")            newState        } catch (t: Throwable) {            Timber.tag(TAG).e(t, "toggleSpeaker failed")            // Return current state on error.            try { am.isSpeakerphoneOn } catch (e: Throwable) { false }        }    }    /**     * Put the current call on hold.     *     * **Limitation**: Android's [android.telecom.Call.hold] API is only     * accessible to the system `InCallService` — third-party apps cannot     * invoke it directly. The Telecom `InCallService` reflection approach     * is fragile across OEMs and disabled on most production devices.     *     * Strategy §"CallEngine" explicitly accepts this limitation:     * "use reflection on InCallService if needed, OR document limitation."     *     * We document the limitation here — `holdCall()` returns `false` on     * all production devices. To actually hold a call, the user must use     * the system in-call UI's Hold button.     *     * @return false — third-party apps cannot hold calls on production Android.     */    fun holdCall(): Boolean {        Timber.tag(TAG).w("holdCall: third-party apps cannot hold calls on production Android (Telecom InCallService is system-only).")        return false    }    /**     * Resume the current call from hold.     *     * Same limitation as [holdCall] — returns false on production devices.     */    fun resumeCall(): Boolean {        Timber.tag(TAG).w("resumeCall: third-party apps cannot resume held calls on production Android.")        return false    }    // ─── Emergency detection ───────────────────────────────────────────────    /** Check if [phoneNumber] is an emergency number. */    internal fun isEmergency(phoneNumber: String): Boolean {        val normalized = phoneNumber.filter { it.isDigit() }        return emergencyNumbers.any { it.filter { d -> d.isDigit() } == normalized }    }    // ─── State management ──────────────────────────────────────────────────    private suspend fun updateState(newState: CallState) {        currentState.set(newState)        _callState.emit(newState)        Timber.tag(TAG).d("Call state: $newState")    }    // ─── Validation Helpers (CRITICAL FIXES #36-#37) ─────────────────────        /**     * CRITICAL FIX #36: Validate phone number format.     */    private fun isValidPhoneNumber(phoneNumber: String): Boolean {        val digitsOnly = phoneNumber.filter { it.isDigit() }        return digitsOnly.length in 7..15 &&                (phoneNumber.startsWith("+") ||                 phoneNumber.matches(Regex("^\\d[0-9 .()-]{6,14}$")))    }        /**     * CRITICAL FIX #37: Mask phone number for logging (PII protection).     */    private fun maskPhoneNumber(phoneNumber: String): String {        if (phoneNumber.length <= 6) return "***"        return phoneNumber.take(3) + "*".repeat(maxOf(0, phoneNumber.length - 6)) + phoneNumber.takeLast(3)    }        private companion object {        private const val TAG = "CallEngine"        private const val BOUNCER_LISTEN_DELAY_MS = 2000L    }}// ──────────────────────────────────────────────────────────────────────────/** Result of placing an outgoing call. */sealed interface CallResult {    data object PLACED : CallResult    data object EMERGENCY_BYPASS : CallResult    data class FAILED(val reason: String) : CallResult}/** Action to take for an incoming call. */sealed interface IncomingCallAction {    /** Ring normally — caller is safe/known. */    data class RingNormally(val callerName: String) : IncomingCallAction    /** Auto-reject — spam detected + autoBlock enabled. */    data class AutoRejected(val classification: com.roshan.persona.connectivity.model.SpamClassification) : IncomingCallAction    /** Ask user — suspicious/spam but autoBlock disabled. */    data class AskUser(val classification: com.roshan.persona.connectivity.model.SpamClassification) : IncomingCallAction    /** Activate Call Bouncer — unknown number, v3 active screening. */    data class ActivateBouncer(        val phoneNumber: String,        val classification: com.roshan.persona.connectivity.model.SpamClassification,    ) : IncomingCallAction}/** Result of the Active Call Bouncer. */sealed interface BouncerResult {    /** Bouncer answered + greeted + waiting for user to accept/reject. */    data class AWAITING_USER_DECISION(        val phoneNumber: String,        val transcription: String?,  // null in v1, STT transcription in v2+    ) : BouncerResult    /** Bouncer auto-rejected (telemarketer keywords detected). */    data class AutoRejected(val reason: String) : BouncerResult    /** Bouncer failed to answer or speak. */    data class FAILED(val reason: String) : BouncerResult}// ──────────────────────────────────────────────────────────────────────────/** * TTS interface for the Call Bouncer. * * Real implementation uses Module 5's EmotionalTtsEngine to speak the * bouncer greeting to the caller. Tests inject a fake. */fun interface BouncerTtsInterface {    /** Speak [text] to the caller. */    fun speak(text: String)}

